class Solution:
    def minMoves(self, positions: List[int]) -> int:
        n = len(positions); a = sorted(positions); best = 0; j = 0
        for i in range(n):
            while a[i] - a[j] > n - 1: j += 1
            best = max(best, i - j + 1)
        return n - best

